"""Scramble String — recursion over every split, with and without a swap.

The multiset check prunes almost every hopeless branch, which is what keeps the
exponential recursion tractable.

Time: O(n^4) with memoisation   Space: O(n^3)
"""
from collections import Counter
from functools import lru_cache


class Solution:
    def isScramble(self, s1: str, s2: str) -> bool:
        @lru_cache(maxsize=None)
        def solve(a: str, b: str) -> bool:
            if a == b:
                return True
            if Counter(a) != Counter(b):
                return False
            n = len(a)
            for i in range(1, n):
                if solve(a[:i], b[:i]) and solve(a[i:], b[i:]):
                    return True
                if solve(a[:i], b[n - i:]) and solve(a[i:], b[:n - i]):
                    return True
            return False

        return solve(s1, s2)
